"""Web-application positioning and original page narratives, applied before render."""
old_scene=scene
def sketch(kind,size=60):return f'<img class="brand-illustration" src="/media/icons/{kind}.svg" width="{size}" height="{size}" alt="" aria-hidden="true">'
def productmark(size=32):return f'<img class="product-mark" src="/brand-emblem-small.webp" width="{size}" height="{size}" alt="" aria-hidden="true">'
def chrome(title,content,kind):return f'<div class="narrative-window" data-narrative="{kind}"><div class="narrative-chrome">{productmark()}<b>{title}</b><span>Örnek çalışma alanı</span></div>{content}</div>'
def scene(kind):
 if kind=='app':return chrome('Veri Burada', '<div class="app-research"><div class="app-sidebar"><span>YENİ ARAŞTIRMA</span><div><small>Bölgeniz</small><b>Beyoğlu, İstanbul</b></div><div><small>İşletme türü</small><b data-app-sector>Mimarlık ofisleri</b></div><div class="app-start-command">İşletmeleri topluca bul</div><p>Telefon · Web sitesi · Adres</p></div><div class="app-research-map">'+sketch('map',160)+'<div class="app-mini-record">'+sketch('architecture',45)+'<span><b data-app-name>Atölye Mimarlık</b><small>Beyoğlu, İstanbul</small></span><i>✓</i></div><div class="app-mini-record">'+sketch('architecture',45)+'<span><b data-app-name>Form Tasarım</b><small>Telefon · Web · Adres</small></span><i>✓</i></div></div></div><div class="narrative-caption">Kurulum gerekmez. Bölgenizi ve sektörünüzü seçerek başlayın.</div>','app')
 if kind=='profile':return chrome('İşletme profiliniz', '<div class="field-profile"><div class="field-identity">'+sketch('architecture',84)+'<div><b>Atölye Mimarlık</b><span>Mimarlık ofisi · Beyoğlu</span></div></div>'+''.join(f'<div class="field-inspect" data-field><span>{label}</span><b>{value}</b><i>✓</i></div>' for label,value in [('Telefon','+90 (212) 000 10 01'),('Web sitesi','atolyemimarlik.example'),('Adres','Meşrutiyet Cd. No: 12, Beyoğlu'),('Puan','4,8 / 5 · Örnek değerlendirme')])+'</div><div class="narrative-caption">Bilgiler kaynağındaki alanlarla eşleştirilir. Bu profil örnektir.</div>','profile')
 if kind=='export':return chrome('Bilgiden çalışma dosyasına','<div class="export-composition"><div class="export-source">'+''.join(f'<div data-source><span>{label}</span><b>{value}</b></div>' for label,value in [('İşletme','Atölye Mimarlık'),('Telefon','+90 (212) 000 10 01'),('Web','atolyemimarlik.example')])+'</div><svg viewBox="0 0 70 150" class="export-bridge" aria-hidden="true"><path d="M0 25H20Q35 25 35 45V75H70M0 75H70M0 125H20Q35 125 35 105V75" pathLength="1"/></svg><div class="export-destination">'+sketch('csv',110)+'<b>işletme-listem.csv</b><span>Türkçe karakterler · Düzenli sütunlar</span><i>Dosyanız hazır ✓</i></div></div><div class="export-preview-row"><span>İşletme</span><span>Telefon</span><span>Web sitesi</span></div><div class="narrative-caption">Örnek kayıtların CSV’ye dönüşümü.</div>','export')
 if kind=='brand':return '<div class="brand-story" data-narrative="brand"><div class="brand-orbit-path"><svg viewBox="0 0 500 330" aria-hidden="true"><path d="M90 92C150 92 150 166 250 166S350 92 410 92M90 250C150 250 150 166 250 166S350 250 410 250" pathLength="1"/></svg></div><div class="brand-story-node node-region">'+sketch('map',70)+'<b>Bir bölge</b></div><div class="brand-story-node node-research">'+sketch('research',70)+'<b>Bir araştırma</b></div><div class="brand-story-center">'+productmark(110)+'</div><div class="brand-story-node node-business">'+sketch('architecture',70)+'<b>İşletme bilgileri</b></div><div class="brand-story-node node-file">'+sketch('csv',70)+'<b>Bir çalışma listesi</b></div><span class="brand-story-caption">İşletmeler orada. Veri burada.</span></div>'
 if kind=='term':return '<div class="term-workbench" data-narrative="term"><div class="scene-top"><b>Kullanım süreniz</b><span>Özellikler aynı kalır.</span></div><div class="term-options" role="group" aria-label="Süreyi karşılaştırın">'+''.join(f'<button type="button" data-term="{m}" aria-pressed="{str(m==6).lower()}">{m} ay</button>' for m in [1,3,6,12])+'</div><div class="term-calendar">'+''.join(f'<span data-month="{i+1}">{m}</span>' for i,m in enumerate([str(i+1)+'. ay' for i in range(12)]))+'</div><div class="term-receipt">'+sketch('webapp',57)+'<div><strong><b data-term-label>6</b> ay kullanım</strong><span>Veri Burada web uygulaması</span></div><b data-term-total>₺1.499</b></div><p class="narrative-caption">Süreyi seçin; toplam fiyatı karşılaştırın. Ödeme bağlantısı daha sonra eklenecek.</p></div>'
 if kind=='help':return '<div class="help-studio" data-narrative="help"><div class="help-visual">'+sketch('research',120)+'<div><span>NEREDEN BAŞLAMALI?</span><b data-help-title>İlk araştırmanız</b><p data-help-description>Bölgenizi ve sektörünüzü seçin, işletmeleri bir listede görün.</p></div></div><div class="help-choices">'+''.join(f'<button type="button" data-help="{k}" aria-pressed="{str(i==0).lower()}">{t}</button>' for i,(k,t) in enumerate([('search','Arama'),('csv','CSV dosyası'),('account','Üyelik')]))+'</div></div>'
 if kind=='mail':return '<div class="mail-studio" data-narrative="mail"><div class="mail-address">'+productmark(35)+'<span><b>Veri Burada</b><small>destek@veriburada.com</small></span></div><div class="mail-envelope"><div class="mail-letter"><span>MESAJINIZ</span><b data-message-subject>Nasıl yardımcı olabiliriz?</b><p data-message-preview>Konu ve mesajınızı aşağıdaki formda hazırlayın.</p><i></i><i></i></div><svg viewBox="0 0 360 180" aria-hidden="true"><path d="M8 16 180 126 352 16v145H8Z" fill="#e5f1e8" stroke="#a9cdb6"/><path d="m8 161 112-91m232 91L240 70" fill="none" stroke="#c3ddcc"/></svg></div><p class="narrative-caption">Taslağı siz hazırlarsınız. Gönderim e-posta uygulamanızdan yapılır.</p></div>'
 if kind=='journey':return '<div class="journal-journey" data-narrative="journey"><div class="journal-route">'+''.join(f'<div data-journal-step>{sketch(kind,85)}<b>{title}</b><span>{detail}</span></div>' for kind,title,detail in [('map','Aramanızı daraltın.','Bölge ve sektör'),('contact','İşletmeyi tanıyın.','Bilgiler ve gözlemler'),('csv','Listenizi hazırlayın.','Kendi çalışma şekliniz')])+'</div><div class="journal-route-line"><i></i></div><p class="narrative-caption">Aramadan çalışma listenize, üç farklı rehber.</p></div>'
 markup=old_scene(kind)
 doc=BeautifulSoup(markup,'html.parser')
 for i,el in enumerate(doc.select('.workspace-record>i')):el.clear();el.append(BeautifulSoup(sketch('clinic' if kind=='sales' else 'architecture',42),'html.parser'))
 top=doc.select_one('.scene-top>b')
 if top:
  top['class']=['scene-top-brand'];top.insert(0,BeautifulSoup(productmark(30),'html.parser'))
 return str(doc)

replacements={'tarayıcı eklentisi':'web uygulaması','Satın alma bağlantısı resmî ürün sayfasına yönlendirir.':'Üyelik ve ödeme bağlantıları uygulama yayınıyla birlikte eklenecektir.','Resmî ürün sayfasında satın alımdan sonra 24 saat içinde aktivasyon ve e-posta ile bilgilendirme belirtilmektedir. Satın alma ekranındaki güncel bilgileri kontrol edin.':'Üyelik akışı gerçek uygulama bağlantısı hazır olduğunda açılacak. Bu önizlemede hesap oluşturulmaz.','Aktivasyon nasıl ilerliyor?':'Üyelik nasıl açılacak?','Kurulum</option>':'Kullanım</option>','Ürün ve lisans':'Ürün ve üyelik','KULLANIM LİSANSI':'KULLANIM SÜRESİ','aylık lisans':'aylık kullanım','kullanım lisansı':'kullanım hakkı','Kullanım lisansı':'Kullanım süresi','Lisans için bilgi alın':'Üyelik için bilgi alın','Lisans</option>':'Üyelik</option>','tarayıcı eklentisidir':'web uygulamasıdır','tarayıcı eklentisiyle':'web uygulamasıyla','Veri Burada eklentisi':'Veri Burada uygulaması','Eklenti, işletme toplama':'Uygulama, işletme toplama','Eklenti,':'Uygulama,','Eklentiyi':'Uygulamayı','eklenti-indir':'basla','Kurulum soruları':'Başlangıç soruları','Kurulum adımlarını görün':'Başlangıç akışını görün','kurulum,':'kullanım,','kurulumu,':'kullanımı,','Veri Burada kurulumu':'Veri Burada kullanımı','Chrome ve Chromium tarayıcılar':'Web uygulaması','Kurulum rehberi':'Başlangıç rehberi','Kurulum, arama veya dosya çıktısı':'Arama, üyelik veya dosya çıktısı','tarayıcı eklentisidir.':'web uygulamasıdır.'}
for page in pages:
 for key in ['title','description','lead','body']:
  for a,b in replacements.items():page[key]=page[key].replace(a,b)
 if page.get('faqs'):
  page['faqs']=[('Telefondan da kullanabilir miyim?','Veri Burada web uygulaması olarak hazırlanıyor. Bu önizlemeyi mobil ve masaüstü tarayıcılarından inceleyebilirsiniz.') if 'Telefonda' in q else (q,a) for q,a in page['faqs']]
  page['body']=faq(page['faqs'])+block('Bir konuda daha yardıma mı ihtiyacınız var?',paras('İlk aramanız, CSV çıktısı veya üyelik hakkında iletişime geçebilirsiniz.')+link('iletisim','Bize yazın'))
by={p['slug']:p for p in pages}
start=by['eklenti-indir'];start.update(slug='basla',title='Veri Burada ile başlayın | Web uygulaması',description='Kurulum gerektirmeyen Veri Burada web deneyimini keşfedin. Bölgenizi ve sektörünüzü seçin, ilk beş örnek kaydı inceleyin.',h1='Tarayıcınızı açın.<br><em>İlk listenize geçin.</em>',lead='İndirme veya eklenti kurulumu yok. Bölgenizi ve sektörünüzü seçerek web uygulamasındaki araştırma akışını deneyin.',scene='app',body=block('İlk aramanız, sizin seçiminizle.',cards([('Neyi araştırıyorsunuz?','Satış, ajans çalışması, yerel iş birliği veya pazar araştırması için bir başlangıç belirleyin.','',''),('Nerede arıyorsunuz?','İl ve ilçenizi seçin. İşletme türünüzü belirleyip hangi bilgi alanlarını görmek istediğinizi işaretleyin.','',''),('Önce çıktıyı görün.','İlk beş örnek kaydı inceleyin. Gerçek uygulama bağlantısı hazır olduğunda hesabınızla aramanıza devam edebilirsiniz.','listeler','Liste örneğini inceleyin')]))+block('Her şey bir çalışma alanında.',paras('İşletme kimliği, telefon, web sitesi ve adres bilgileri aynı listede buluşur. CSV çıktısıyla verileri kendi çalışma aracınıza taşıyabilirsiniz.','Bu sayfadaki deneyim örnek modda çalışır. Gerçek arama, üyelik ve ödeme bağlantıları uygulama yayınıyla birlikte eklenecek.')))
by['ozellikler']['scene']='profile';by['listeler']['scene']='export';by['hakkimizda']['scene']='brand';by['pricing']['scene']='term';by['sss']['scene']='help';by['iletisim']['scene']='mail';by['blog']['scene']='journey'
by['nasil-calisir']['body']=by['nasil-calisir']['body'].replace('Çalışmak istediğiniz il','Çalışmak istediğiniz il')
for page in pages:
 if page.get('article'):
  kind='local' if 'bolgeye' in page['slug'] else 'agency' if 'ajanslar' in page['slug'] else 'export'
  visual='<figure class="article-demo">'+scene(kind)+'<figcaption>Rehberde anlatılan çalışma akışının temsili görünümü.</figcaption></figure>'
  page['body']=page['body'].replace('<div class="article-prose">','<div class="article-prose">'+visual)
for page in pages:
 doc=BeautifulSoup(page['body'],'html.parser')
 for i,el in enumerate(doc.select('.journal-art')):
  el.clear();el['class']=['journal-art','cover-art','cover-'+str(i)]
  if i==0:cover='<div class="cover-map"><div class="cover-search">Beyoğlu, İstanbul <b>İşletme araştırması</b></div><span class="cover-pin cp-1"></span><span class="cover-pin cp-2"></span><span class="cover-pin cp-3"></span><div class="cover-record">'+sketch('architecture',44)+'<span><b>Bir bölge seçin.</b><small>İşletmeleri birlikte bulun.</small></span><i>✓</i></div></div>'
  elif i==1:cover='<div class="cover-agency"><div class="cover-site"><img src="/media/restaurant.webp" width="1100" height="825" alt="" loading="lazy"><div><b>Pera Mutfak</b><span>Mevsimden sofranıza.</span></div></div><div class="cover-analysis">'+sketch('webapp',50)+'<b>Tekliften önce<br>işletmeyi tanıyın.</b><span>Web sitesi <i>✓</i></span><span>İletişim <i>✓</i></span></div></div>'
  else:cover='<div class="cover-spreadsheet"><div class="cover-sheet-top">'+sketch('csv',46)+'<b>işletme-listem.csv</b><span>CSV</span></div><div class="cover-sheet-head"><span>İşletme</span><span>Telefon</span><span>Web sitesi</span></div>'+''.join('<div class="cover-sheet-row"><span>'+name+'</span><i></i><b>✓</b></div>' for name in ['Atölye Mimarlık','Form Tasarım','Studio Mimarlık'])+'<div class="cover-sheet-foot">Düzenli sütunlar. Kendi çalışma listeniz.</div></div>'
  el.append(BeautifulSoup(cover,'html.parser'))
 for i,el in enumerate(doc.select('.editorial-cards .card-index')):
  el.clear();el.append(BeautifulSoup(sketch(['map','contact','csv','research'][i%4],56),'html.parser'));el['class']=['card-illustration']
 for el in doc.select('.directory-table tbody th>b'):el.clear();el.append(BeautifulSoup(sketch('architecture',42),'html.parser'))
 page['body']=str(doc)
MENU=MENU.replace('/eklenti-indir/','/basla/').replace('Kurulum rehberi','Başlangıç rehberi')
FOOTER=FOOTER.replace('/eklenti-indir/','/basla/').replace('Eklentiyi indir','Uygulamayı keşfedin')
